package com.example.urlshortener.preview;

import com.fasterxml.jackson.annotation.JsonInclude;
import com.fasterxml.jackson.annotation.JsonProperty;

import java.time.Instant;

/**
 * Value object holding preview metadata for a short code's target URL.
 */
@JsonInclude(JsonInclude.Include.ALWAYS)
public class PreviewDocument {

    @JsonProperty("shortCode")
    private final String shortCode;

    @JsonProperty("targetUrl")
    private final String targetUrl;

    @JsonProperty("title")
    private final String title;

    @JsonProperty("description")
    private final String description;

    @JsonProperty("fetchedAt")
    private final Instant fetchedAt;

    @JsonProperty("cacheExpiresAt")
    private final Instant cacheExpiresAt;

    // For JSON deserialization
    public PreviewDocument() {
        this.shortCode = null;
        this.targetUrl = null;
        this.title = null;
        this.description = null;
        this.fetchedAt = null;
        this.cacheExpiresAt = null;
    }

    private PreviewDocument(Builder builder) {
        this.shortCode = builder.shortCode;
        this.targetUrl = builder.targetUrl;
        this.title = builder.title;
        this.description = builder.description;
        this.fetchedAt = builder.fetchedAt;
        this.cacheExpiresAt = builder.cacheExpiresAt;
    }

    public String getShortCode() {
        return shortCode;
    }

    public String getTargetUrl() {
        return targetUrl;
    }

    public String getTitle() {
        return title;
    }

    public String getDescription() {
        return description;
    }

    public Instant getFetchedAt() {
        return fetchedAt;
    }

    public Instant getCacheExpiresAt() {
        return cacheExpiresAt;
    }

    public boolean isExpired() {
        return cacheExpiresAt != null && Instant.now().isAfter(cacheExpiresAt);
    }

    public static Builder builder() {
        return new Builder();
    }

    public static class Builder {
        private String shortCode;
        private String targetUrl;
        private String title;
        private String description;
        private Instant fetchedAt;
        private Instant cacheExpiresAt;

        public Builder shortCode(String shortCode) {
            this.shortCode = shortCode;
            return this;
        }

        public Builder targetUrl(String targetUrl) {
            this.targetUrl = targetUrl;
            return this;
        }

        public Builder title(String title) {
            this.title = title;
            return this;
        }

        public Builder description(String description) {
            this.description = description;
            return this;
        }

        public Builder fetchedAt(Instant fetchedAt) {
            this.fetchedAt = fetchedAt;
            return this;
        }

        public Builder cacheExpiresAt(Instant cacheExpiresAt) {
            this.cacheExpiresAt = cacheExpiresAt;
            return this;
        }

        public PreviewDocument build() {
            if (shortCode == null || shortCode.isBlank()) {
                throw new IllegalStateException("shortCode must not be null or blank");
            }
            if (targetUrl == null || targetUrl.isBlank()) {
                throw new IllegalStateException("targetUrl must not be null or blank");
            }
            if (fetchedAt == null) {
                throw new IllegalStateException("fetchedAt must not be null");
            }
            if (cacheExpiresAt == null) {
                throw new IllegalStateException("cacheExpiresAt must not be null");
            }
            return new PreviewDocument(this);
        }
    }

    @Override
    public String toString() {
        return "PreviewDocument{" +
                "shortCode='" + shortCode + '\'' +
                ", targetUrl='" + targetUrl + '\'' +
                ", title='" + title + '\'' +
                ", description='" + description + '\'' +
                ", fetchedAt=" + fetchedAt +
                ", cacheExpiresAt=" + cacheExpiresAt +
                '}';
    }
}
