package com.example.urlshortener.preview;

import org.springframework.boot.context.properties.ConfigurationProperties;
import org.springframework.stereotype.Component;

/**
 * Externalized configuration for the preview feature.
 * All timeout and TTL values can be tuned via application properties
 * without a code change.
 *
 * Defaults:
 *   fetchTimeoutMs    = 3000  (per-fetch HTTP timeout)
 *   cacheTimeoutMs    = 3000  (overall SLA timeout for the cache call)
 *   cacheTtlSeconds   = 86400 (24 hours)
 *   maxRedirects      = 5
 */
@Component
@ConfigurationProperties(prefix = "preview")
public class PreviewConfig {

    private long fetchTimeoutMs = 3_000L;
    private long cacheTimeoutMs = 3_000L;
    private long cacheTtlSeconds = 86_400L;
    private int maxRedirects = 5;
    private int staleRetryAfterSeconds = 30;

