package com.example.urlshortener.preview;

import java.util.Optional;

/**
 * Read/write abstraction over the cache store (Redis or in-process fallback).
 * Keys on short code; stores serialized PreviewDocument with a configurable TTL.
 */
public interface PreviewCache {

    /**
     * Retrieve a cached PreviewDocument for the given short code.
     *
     * @param code the short code
     * @return an Optional containing the document if present (may be stale), empty if absent
     */
    Optional<PreviewDocument> get(String code);

    /**
     * Write a PreviewDocument to the cache using SET NX semantics to prevent stampede.
     * TTL is governed by {@link PreviewConfig#getCacheTtlSeconds()}.
     *
     * @param document the document to cache
     */
    void put(PreviewDocument document);

    /**
     * Forcibly overwrite an existing cached entry (used for stale-while-revalidate refresh).
     *
     * @param document the document to cache
     */
    void refresh(PreviewDocument document);

    /**
     * Remove the cached entry for the given short code, if any.
     *
     * @param code the short code
     */
    void evict(String code);
}
