package com.example.urlshortener.preview;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.SerializationFeature;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.autoconfigure.condition.ConditionalOnBean;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.stereotype.Component;

import java.time.Duration;
import java.util.Optional;

/**
 * Redis-backed implementation of {@link PreviewCache}.
 * Key schema: preview:{code}
 * Value: JSON-serialised PreviewDocument
 * TTL: cacheTtlSeconds from PreviewConfig
 */
@Component
@ConditionalOnBean(StringRedisTemplate.class)
public class RedisPreviewCache implements PreviewCache {

    private static final Logger log = LoggerFactory.getLogger(RedisPreviewCache.class);
    private static final String KEY_PREFIX = "preview:";

    private final StringRedisTemplate redisTemplate;
    private final PreviewConfig config;
    private final ObjectMapper objectMapper;

    @Autowired
    public RedisPreviewCache(StringRedisTemplate redisTemplate, PreviewConfig config) {
        this.redisTemplate = redisTemplate;
        this.config = config;
        this.objectMapper = buildObjectMapper();
    }

    @Override
    public Optional<PreviewDocument> get(String code) {
        String key = key(code);
        try {
            String json = redisTemplate.opsForValue().get(key);
            if (json == null) {
                return Optional.empty();
            }
            return Optional.of(objectMapper.readValue(json, PreviewDocument.class));
        } catch (Exception e) {
            log.warn("Failed to read preview from Redis for code '{}': {}", code, e.getMessage());
            return Optional.empty();
        }
    }

    @Override
    public void put(PreviewDocument document) {
        String key = key(document.getShortCode());
        String json = serialize(document);
        if (json == null) return;
        // SET NX: only write if key does not already exist (prevents stampede)
        Boolean set = redisTemplate.opsForValue()
                .setIfAbsent(key, json, Duration.ofSeconds(config.getCacheTtlSeconds()));
        if (Boolean.FALSE.equals(set)) {
            log.debug("Cache entry for '{}' already exists; skipping SET NX", document.getShortCode());
        }
    }

    @Override
    public void refresh(PreviewDocument document) {
        String key = key(document.getShortCode());
        String json = serialize(document);
        if (json == null) return;
        redisTemplate.opsForValue().set(key, json, Duration.ofSeconds(config.getCacheTtlSeconds()));
        log.debug("Refreshed cache entry for '{}'", document.getShortCode());
    }

    @Override
    public void evict(String code) {
        redisTemplate.delete(key(code));
    }

    private String key(String code) {
        return KEY_PREFIX + code;
    }

    private String serialize(PreviewDocument document) {
        try {
            return objectMapper.writeValueAsString(document);
        } catch (JsonProcessingException e) {
            log.error("Failed to serialize PreviewDocument for '{}': {}", document.getShortCode(), e.getMessage());
            return null;
        }
    }

    private static ObjectMapper buildObjectMapper() {
        ObjectMapper mapper = new ObjectMapper();
        mapper.registerModule(new JavaTimeModule());
        mapper.disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
        return mapper;
    }
}
