package com.example.urlshortener.preview;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.boot.autoconfigure.condition.ConditionalOnMissingBean;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.stereotype.Component;

import java.time.Instant;
import java.util.Map;
import java.util.Optional;
import java.util.concurrent.ConcurrentHashMap;

/**
 * In-process fallback cache used when Redis is not available.
 * Uses a ConcurrentHashMap; expiry is checked lazily on read.
 */
@Component
@ConditionalOnMissingBean(StringRedisTemplate.class)
public class InProcessPreviewCache implements PreviewCache {

    private static final Logger log = LoggerFactory.getLogger(InProcessPreviewCache.class);

    private final Map<String, PreviewDocument> store = new ConcurrentHashMap<>();

    @Override
    public Optional<PreviewDocument> get(String code) {
        PreviewDocument doc = store.get(code);
        if (doc == null) {
            return Optional.empty();
        }
        if (doc.isExpired()) {
            log.debug("In-process cache entry for '{}' is expired; removing", code);
            store.remove(code);
            return Optional.empty();
        }
        return Optional.of(doc);
    }

    @Override
    public void put(PreviewDocument document) {
        // putIfAbsent for NX-like semantics
        store.putIfAbsent(document.getShortCode(), document);
    }

    @Override
    public void refresh(PreviewDocument document) {
        store.put(document.getShortCode(), document);
    }

    @Override
    public void evict(String code) {
        store.remove(code);
    }
}
